"""Normalization helpers for Perses Normal Form (PNF)."""

from __future__ import annotations

import copy
from dataclasses import dataclass

from reduction.grammar import Grammar, GrammarRule, RuleType


QUANTIFIER_TYPES = {
    RuleType.KLEENE_STAR,
    RuleType.KLEENE_PLUS,
    RuleType.OPTIONAL,
}


@dataclass
class PNFNormalizer:
    """Normalize a ``Grammar`` into the reduced PNF shape used by the reducers."""

    _counter: int = 0

    def normalize(self, grammar: Grammar) -> Grammar:
        working = copy.deepcopy(grammar)
        self._hoist_nested_rules(working)
        self._remove_unreachable_rules(working)
        self._inline_alias_rules(working)
        self._remove_immediate_recursion(working)
        self._hoist_nested_rules(working)
        self._inline_alias_rules(working)
        self._remove_unreachable_rules(working)
        return working

    def _hoist_nested_rules(self, grammar: Grammar) -> None:
        changed = True
        while changed:
            changed = False
            for rule in list(grammar.rules.values()):
                replacement: list[str | GrammarRule] = []
                for index, symbol in enumerate(rule.symbols):
                    if isinstance(symbol, GrammarRule):
                        name = symbol.name or self._fresh_name(rule.name, f"embedded_{index}")
                        nested = copy.deepcopy(symbol)
                        nested.name = name
                        grammar.rules[name] = nested
                        replacement.append(name)
                        changed = True
                    else:
                        replacement.append(symbol)
                rule.symbols = replacement

    def _remove_unreachable_rules(self, grammar: Grammar) -> None:
        reachable: set[str] = set()
        stack = [grammar.start_symbol]
        while stack:
            name = stack.pop()
            if name in reachable or name not in grammar.rules:
                continue
            reachable.add(name)
            for symbol in grammar.rules[name].symbols:
                if isinstance(symbol, str) and symbol in grammar.rules:
                    stack.append(symbol)
        grammar.rules = {
            name: rule
            for name, rule in grammar.rules.items()
            if name in reachable
        }

    def _inline_alias_rules(self, grammar: Grammar) -> None:
        aliases: dict[str, str] = {}
        for name, rule in list(grammar.rules.items()):
            if name == grammar.start_symbol:
                continue
            if rule.rule_type in QUANTIFIER_TYPES:
                continue
            if len(rule.symbols) != 1:
                continue
            target = rule.symbols[0]
            if isinstance(target, str) and target in grammar.rules:
                aliases[name] = target

        if not aliases:
            return

        for rule in grammar.rules.values():
            updated: list[str | GrammarRule] = []
            for symbol in rule.symbols:
                if isinstance(symbol, str):
                    updated.append(self._resolve_alias(symbol, aliases))
                else:
                    updated.append(symbol)
            rule.symbols = updated

        for alias in aliases:
            grammar.rules.pop(alias, None)

    def _remove_immediate_recursion(self, grammar: Grammar) -> None:
        for name in list(grammar.rules.keys()):
            if name not in grammar.rules:
                continue
            rule = grammar.rules[name]
            if rule.rule_type != RuleType.ALTERNATION:
                continue

            alternatives = [symbol for symbol in rule.symbols if isinstance(symbol, str)]
            left_recursive: list[list[str]] = []
            right_recursive: list[list[str]] = []
            base_alternatives: list[str] = []

            for alternative_name in alternatives:
                alternative = grammar.rules.get(alternative_name)
                if alternative is None:
                    base_alternatives.append(alternative_name)
                    continue
                symbols = [sym for sym in alternative.symbols if isinstance(sym, str)]
                if alternative.rule_type == RuleType.SEQUENCE and symbols and symbols[0] == name:
                    suffix = symbols[1:]
                    if suffix:
                        left_recursive.append(suffix)
                    continue
                if alternative.rule_type == RuleType.SEQUENCE and symbols and symbols[-1] == name:
                    prefix = symbols[:-1]
                    if prefix:
                        right_recursive.append(prefix)
                    continue
                if alternative_name != name:
                    base_alternatives.append(alternative_name)

            if left_recursive and base_alternatives:
                self._rewrite_left_recursion(grammar, name, base_alternatives, left_recursive)
            elif right_recursive and base_alternatives:
                self._rewrite_right_recursion(grammar, name, base_alternatives, right_recursive)

    def _rewrite_left_recursion(
        self,
        grammar: Grammar,
        name: str,
        bases: list[str],
        suffixes: list[list[str]],
    ) -> None:
        base_rule_name = self._wrap_alternatives(grammar, name, "base", bases)
        item_names = [self._ensure_sequence_rule(grammar, name, "left_item", suffix) for suffix in suffixes]
        item_rule_name = self._wrap_alternatives(grammar, name, "left_items", item_names)
        repeat_name = self._fresh_name(name, "tail")
        grammar.add_rule(GrammarRule(repeat_name, RuleType.KLEENE_STAR, [item_rule_name]))
        grammar.rules[name] = GrammarRule(name, RuleType.SEQUENCE, [base_rule_name, repeat_name])

    def _rewrite_right_recursion(
        self,
        grammar: Grammar,
        name: str,
        bases: list[str],
        prefixes: list[list[str]],
    ) -> None:
        item_names = [self._ensure_sequence_rule(grammar, name, "right_item", prefix) for prefix in prefixes]
        item_rule_name = self._wrap_alternatives(grammar, name, "right_items", item_names)
        repeat_name = self._fresh_name(name, "head")
        grammar.add_rule(GrammarRule(repeat_name, RuleType.KLEENE_STAR, [item_rule_name]))
        base_rule_name = self._wrap_alternatives(grammar, name, "base", bases)
        grammar.rules[name] = GrammarRule(name, RuleType.SEQUENCE, [repeat_name, base_rule_name])

    def _wrap_alternatives(
        self,
        grammar: Grammar,
        owner: str,
        suffix: str,
        alternatives: list[str],
    ) -> str:
        if len(alternatives) == 1:
            return alternatives[0]
        rule_name = self._fresh_name(owner, suffix)
        grammar.add_rule(GrammarRule(rule_name, RuleType.ALTERNATION, list(alternatives)))
        return rule_name

    def _ensure_sequence_rule(
        self,
        grammar: Grammar,
        owner: str,
        suffix: str,
        symbols: list[str],
    ) -> str:
        if len(symbols) == 1:
            return symbols[0]
        rule_name = self._fresh_name(owner, suffix)
        grammar.add_rule(GrammarRule(rule_name, RuleType.SEQUENCE, list(symbols)))
        return rule_name

    def _resolve_alias(self, symbol: str, aliases: dict[str, str]) -> str:
        target = symbol
        seen = set()
        while target in aliases and target not in seen:
            seen.add(target)
            target = aliases[target]
        return target

    def _fresh_name(self, owner: str, suffix: str) -> str:
        self._counter += 1
        return f"{owner}_{suffix}_{self._counter}"


def normalize_grammar(grammar: Grammar) -> Grammar:
    """Return a normalized copy of ``grammar``."""
    return PNFNormalizer().normalize(grammar)

