"""Simplified Perses-style syntax-guided reducer."""

from __future__ import annotations

import heapq
from dataclasses import dataclass

from reduction.grammar import Grammar, RuleType
from reduction.parser import Parser
from reduction.pnf import normalize_grammar
from reduction.property_test import PropertyTester
from reduction.reducer import AbstractReducer
from reduction.tree import NodeType, SparTreeNode
from reduction.tree_utils import (
    iter_nodes,
    line_span,
    node_at,
    parent_at,
    reindent_lines,
    replace_lines,
    target_indent_for,
)


LIST_RULE_TYPES = {RuleType.KLEENE_STAR, RuleType.KLEENE_PLUS}


@dataclass(order=True)
class _QueueEntry:
    priority: int
    order: int
    path: tuple[int, ...]


class PersesReducer(AbstractReducer):
    """Syntax-guided reducer inspired by Perses."""

    def __init__(self, grammar: Grammar):
        self.grammar = normalize_grammar(grammar)
        self.parser = Parser(self.grammar)

    @property
    def name(self) -> str:
        return "perses"

    def reduce(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        working = self.parser.parse(tree.to_source())

        while True:
            candidate = self._reduce_once(working, tester)
            if candidate.token_count() >= working.token_count():
                return working
            working = candidate

    def _reduce_once(self, tree: SparTreeNode, tester: PropertyTester) -> SparTreeNode:
        queue = self._priority_queue(tree)
        while queue:
            entry = heapq.heappop(queue)
            node = node_at(tree, entry.path)
            if node is None or node.node_type == NodeType.TOKEN or node.token_count() == 0:
                continue

            if self._is_list_node(node):
                reduced = self._reduce_list_node(tree, entry.path, tester)
            else:
                reduced = self._replace_with_compatible_subtree(tree, entry.path, tester)

            if reduced.token_count() < tree.token_count():
                return reduced

        return tree

    def _priority_queue(self, tree: SparTreeNode) -> list[_QueueEntry]:
        queue: list[_QueueEntry] = []
        order = 0
        for path, node in iter_nodes(tree):
            if node.node_type == NodeType.TOKEN or node.token_count() == 0:
                continue
            heapq.heappush(queue, _QueueEntry(-node.token_count(), order, path))
            order += 1
        return queue

    def _is_list_node(self, node: SparTreeNode) -> bool:
        rule = self.grammar.expected_rule(node.rule_name)
        return rule is not None and rule.rule_type in LIST_RULE_TYPES

    def _reduce_list_node(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
    ) -> SparTreeNode:
        node = node_at(tree, path)
        if node is None:
            return tree

        rule = self.grammar.expected_rule(node.rule_name)
        if rule is None:
            return tree

        min_keep = 1 if rule.rule_type == RuleType.KLEENE_PLUS else 0
        if len(node.children) <= min_keep:
            return tree

        return self._ddmin_children(tree, path, tester, min_keep)

    def _ddmin_children(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
        min_keep: int,
    ) -> SparTreeNode:
        granularity = 2
        working = tree

        while True:
            node = node_at(working, path)
            if node is None:
                return working

            size = len(node.children)
            if size <= min_keep:
                return working

            partitions = self._split_indices(size, granularity)
            changed = False

            for partition in partitions:
                keep = [index for index in range(size) if index not in partition]
                if len(keep) < min_keep:
                    continue
                candidate = self._candidate_with_child_subset(working, path, keep)
                accepted = self._accept_tree(candidate, tester)
                if accepted is not None:
                    working = accepted
                    granularity = max(granularity - 1, 2)
                    changed = True
                    break

            if changed:
                continue

            for partition in partitions:
                if len(partition) < min_keep or len(partition) == size:
                    continue
                candidate = self._candidate_with_child_subset(working, path, partition)
                accepted = self._accept_tree(candidate, tester)
                if accepted is not None:
                    working = accepted
                    granularity = 2
                    changed = True
                    break

            if changed:
                continue

            if granularity >= size:
                return working
            granularity = min(size, granularity * 2)

    def _candidate_with_child_subset(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        keep: list[int],
    ) -> SparTreeNode:
        candidate = tree.clone()
        node = node_at(candidate, path)
        if node is None:
            return candidate
        keep_set = set(keep)
        node.children = [
            child
            for index, child in enumerate(node.children)
            if index in keep_set
        ]
        return candidate

    def _replace_with_compatible_subtree(
        self,
        tree: SparTreeNode,
        path: tuple[int, ...],
        tester: PropertyTester,
    ) -> SparTreeNode:
        target = node_at(tree, path)
        if target is None or not path:
            return tree

        replacements = [
            candidate
            for candidate_path, candidate in iter_nodes(tree)
            if candidate_path != path
            and candidate.rule_name == target.rule_name
            and candidate.token_count() < target.token_count()
            and candidate.token_count() > 0
        ]
        replacements.sort(key=lambda node: node.token_count())

        if not replacements:
            return tree

        original_source = tree.to_source()
        span = line_span(target)
        if span is None:
            return tree
        target_indent = target_indent_for(target)

        for replacement in replacements:
            replacement_lines = replacement.to_source().splitlines()
            replacement_lines = reindent_lines(replacement_lines, target_indent)
            candidate_source = replace_lines(original_source, span[0], span[1], replacement_lines)
            accepted = self._accept_source(candidate_source, tester)
            if accepted is not None:
                return accepted

        return tree

    def _accept_tree(
        self,
        candidate: SparTreeNode,
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        return self._accept_source(candidate.to_source(), tester)

    def _accept_source(
        self,
        source: str,
        tester: PropertyTester,
    ) -> SparTreeNode | None:
        if not source.strip():
            return None
        if not tester.test(source):
            return None
        return self.parser.parse(source)

    def _split_indices(self, size: int, n: int) -> list[list[int]]:
        n = max(1, min(n, size))
        base = size // n
        remainder = size % n
        result: list[list[int]] = []
        start = 0
        for index in range(n):
            width = base + (1 if index < remainder else 0)
            end = start + width
            result.append(list(range(start, end)))
            start = end
        return [part for part in result if part]

